'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const form = $('#quote-form'); let step=0; let photos=[];
const config=window.SITE_CONFIG;
const serviceNames=['Objektbetreuung','Reinigung','Gartenpflege'];
const menu=$('.menu'); menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));$('#navigation').classList.toggle('open',open)});
$$('nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');$('#navigation').classList.remove('open')}));
menu.addEventListener('keydown',e=>{if(e.key==='Escape'){menu.setAttribute('aria-expanded','false');$('#navigation').classList.remove('open')}});
const val = id => $('#'+id).value.trim();
const data = () => ({services:$$('[name=service]:checked').map(i=>i.value),frequency:$('[name=frequency]:checked')?.value||'',property:val('property'),postcode:val('postcode'),city:val('city'),description:val('description'),area:$('#unknown').checked?'Weiß ich nicht':val('area-size'),timeframe:val('timeframe'),name:val('name'),email:val('email'),phone:val('phone'),preferred:val('preferred'),photos:photos.map(p=>({name:p.file.name,size:p.file.size,type:p.file.type}))});
function error(id,message){const box=$('#'+id+'-error');if(box)box.textContent=message;const fields=id==='service'?$$('[name=service]'):id==='frequency'?$$('[name=frequency]'):[$('#'+id)].filter(Boolean);fields.forEach(el=>{el.setAttribute('aria-invalid',String(!!message));el.setAttribute('aria-describedby',id+'-error')});return !message;}
function validate(s){const d=data();let ok=true;const check=(id,msg)=>{if(!error(id,msg))ok=false};if(s===0){check('service',d.services.length?'':'Bitte wählen Sie mindestens eine Leistung.');check('frequency',d.frequency?'':'Bitte wählen Sie einmalige oder regelmäßige Unterstützung.');check('property',d.property?'':'Bitte wählen Sie die Art Ihres Objekts.')}if(s===1){check('postcode',/^\d{5}$/.test(d.postcode)?'':'Bitte geben Sie eine fünfstellige deutsche Postleitzahl ein.');check('city',d.city?'':'Bitte geben Sie den Ort Ihres Objekts an.');check('description',d.description?'':'Bitte beschreiben Sie kurz die gewünschten Arbeiten.')}if(s===2){check('name',d.name?'':'Bitte geben Sie Ihren Namen an.');check('email',validEmail()?'':'Bitte geben Sie eine gültige E-Mail-Adresse ein.');check('phone',!d.phone||validPhone()?'':'Bitte geben Sie eine gültige Telefonnummer mit mindestens 6 Ziffern ein.');check('preferred',d.preferred==='Telefon'&&!validPhone()?'Bitte ergänzen Sie eine Telefonnummer oder wählen Sie E-Mail.':d.preferred==='E-Mail'&&!validEmail()?'Bitte ergänzen Sie eine gültige E-Mail-Adresse.':'')}if(!ok)$('[data-step="'+s+'"] [aria-invalid=true]')?.focus();return ok;}
function showStep(n,focus=true){step=n;$$('.form-step').forEach((el,i)=>el.hidden=i!==n);$$('.progress li').forEach((el,i)=>{if(i===n)el.setAttribute('aria-current','step');else el.removeAttribute('aria-current')});$('#back').hidden=n===0;$('#next').hidden=n===2;$('#submit').hidden=n!==2;$('#next').textContent=n===0?'Weiter zum Objekt':'Weiter zum Kontakt';if(n===2){updateContact();summary()}if(focus){$('[data-step="'+n+'"] h3').focus({preventScroll:true});$('#anfrage').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}}
$('#next').addEventListener('click',()=>{if(validate(step))showStep(step+1)});$('#back').addEventListener('click',()=>showStep(step-1));
function startService(service){if(!serviceNames.includes(service))throw new Error('Ungültige Leistung');const input=$$('[name=service]').find(i=>i.value===service);input.checked=true;error('service','');form.hidden=false;$('#complete').hidden=true;showStep(0);return {step:1,selectedServices:data().services};}
$$('.service-cta').forEach(b=>b.addEventListener('click',()=>startService(b.dataset.service)));
$$('[data-edit]').forEach(b=>b.addEventListener('click',()=>showStep(Number(b.dataset.edit))));
$('#unknown').addEventListener('change',()=>{$('#area-size').disabled=$('#unknown').checked});
function validEmail(){return !!val('email')&&$('#email').validity.valid}function validPhone(){return /^[+()\d\s/.-]+$/.test(val('phone'))&&val('phone').replace(/\D/g,'').length>=6}
function updateContact(){const select=$('#preferred');const email=validEmail(),phone=validPhone();select.options[1].disabled=!email;select.options[2].disabled=!phone;if((select.value==='Telefon'&&!phone)||(select.value==='E-Mail'&&!email))select.value='';if(!select.value&&email)select.value='E-Mail';select.options[0].textContent=email||phone?'Keine Präferenz':'Bitte erst Kontaktdaten eingeben';}
['email','phone'].forEach(id=>$('#'+id).addEventListener('input',updateContact));
form.addEventListener('input',e=>{if(step===2)summary();const id=e.target.name==='service'?'service':e.target.name==='frequency'?'frequency':e.target.id;if(id&&$('#'+id+'-error'))error(id,'')});
function summary(){const d=data(),dl=document.createElement('dl');const rows=[['Leistungen',d.services.join(', ')],['Betreuung / Objekt',d.frequency+' · '+d.property],['Standort',d.postcode+' '+d.city],['Ihr Anliegen',d.description],['Größe / Fläche',d.area||'Nicht angegeben'],['Zeitraum',d.timeframe||'Nach Absprache'],['Fotos',d.photos.length?d.photos.map(p=>p.name).join(', '):'Keine Fotos'],['Kontakt',[d.name,d.email,d.phone].filter(Boolean).join(' · ')],['Bevorzugter Kontaktweg',d.preferred||'Keine Präferenz']];for(const [title,value] of rows){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=title;dd.textContent=value;dl.append(dt,dd)}$('#summary-content').replaceChildren(dl)}
function renderPhotos(){const root=$('#previews');root.replaceChildren();photos.forEach((p,i)=>{const figure=document.createElement('figure'),img=document.createElement('img'),name=document.createElement('small'),button=document.createElement('button');img.src=p.url;img.alt='Vorschau: '+p.file.name;name.textContent=p.file.name;button.type='button';button.textContent='Entfernen';button.setAttribute('aria-label',p.file.name+' entfernen');button.addEventListener('click',()=>{URL.revokeObjectURL(p.url);photos.splice(i,1);renderPhotos();$('#photos').focus();$('#photos-error').textContent=''});figure.append(img,name,button);root.append(figure)})}
async function imageIsValid(file){const bytes=new Uint8Array(await file.slice(0,16).arrayBuffer());const jpeg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;const png=[137,80,78,71,13,10,26,10].every((v,i)=>bytes[i]===v);const webp=String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP';if(!((file.type==='image/jpeg'&&jpeg)||(file.type==='image/png'&&png)||(file.type==='image/webp'&&webp)))return false;try{const bitmap=await createImageBitmap(file);bitmap.close();return true}catch{return false}}
$('#photos').addEventListener('change',async e=>{const files=[...e.target.files],messages=[];e.target.disabled=true;for(const file of files){if(photos.length>=5){messages.push('Es sind maximal fünf Fotos möglich. Entfernen Sie zunächst ein Foto.');break}if(!['image/jpeg','image/png','image/webp'].includes(file.type)||! /\.(jpe?g|png|webp)$/i.test(file.name)){messages.push(file.name+': Bitte JPG, PNG oder WebP verwenden.');continue}if(file.size>10*1024*1024){messages.push(file.name+': Die Datei ist größer als 10 MB.');continue}if(!await imageIsValid(file)){messages.push(file.name+': Die Datei konnte nicht als gültiges Bild gelesen werden.');continue}photos.push({file,url:URL.createObjectURL(file)})}renderPhotos();$('#photos-error').textContent=messages.join(' ');e.target.value='';e.target.disabled=false});
async function submitInquiry(payload,files){if(!config.formEndpoint)return {mode:'demo'};const endpoint=new URL(config.formEndpoint,location.href);if(endpoint.origin!==location.origin||endpoint.protocol!=='https:')throw new Error('Die Formularanbindung ist noch nicht korrekt eingerichtet.');const body=new FormData();body.append('inquiry',JSON.stringify(payload));files.forEach(p=>body.append('photos',p.file));const response=await fetch(endpoint,{method:'POST',body,credentials:'same-origin'});if(!response.ok)throw new Error('Die Anfrage konnte nicht übermittelt werden. Bitte versuchen Sie es erneut.');const result=await response.json();if(result.status!=='accepted'||typeof result.id!=='string')throw new Error('Der Eingang konnte nicht bestätigt werden. Bitte kontaktieren Sie den Betrieb direkt.');return {mode:'live',id:result.id}}
form.addEventListener('submit',async e=>{e.preventDefault();if(step!==2){if(validate(step))showStep(step+1);return}for(let i=0;i<3;i++){if(!validate(i)){showStep(i);validate(i);return}}const btn=$('#submit');btn.disabled=true;try{const result=await submitInquiry(data(),photos);if(result.mode==='live'){$('#complete .eyebrow').textContent='ANFRAGE EINGEGANGEN';$('#complete h3').textContent='Ihre Anfrage wurde entgegengenommen.';$('#complete p').textContent='Ihre Vorgangsnummer: '+result.id;}form.hidden=true;$('#complete').hidden=false;$('#complete').focus();}catch(err){let el=$('#submit-error');if(!el){el=document.createElement('p');el.id='submit-error';el.className='error';el.setAttribute('role','alert');$('.form-controls').after(el)}el.textContent=err.message}finally{btn.disabled=false}});
$('#review').addEventListener('click',()=>{form.hidden=false;$('#complete').hidden=true;showStep(2)});
const legal=$('#legal');let returnFocus;
const legalCopy={imprint:{title:'Impressum – Demo',html:'<p>Dies ist ein Portfolio-Projekt unter dem fiktiven Arbeitstitel WERK & GRÜN. Es wird kein realer Hausmeisterbetrieb dargestellt.</p><h3>Vor dem echten Betrieb zu ergänzen</h3><ul><li>Vollständiger Name / Unternehmensname und Rechtsform</li><li>Ladungsfähige Anschrift und verantwortliche Person</li><li>Telefonnummer und E-Mail-Adresse</li><li>Weitere für den tatsächlichen Betrieb erforderliche Angaben</li></ul><p><strong>Unternehmensdaten: [Platzhalter]</strong></p>'},privacy:{title:'Datenschutz – Demo',html:'<p>Das Anfrageformular arbeitet ohne angebundenen Versanddienst. Eingaben verbleiben während der geöffneten Seite im Arbeitsspeicher Ihres Browsers. Ausgewählte Bilder werden nur lokal als Vorschau angezeigt. Beim Neuladen gehen die Eingaben verloren.</p><p>Diese Seite verwendet keine Analysewerkzeuge, keine externen Karten und keine Speicherung Ihrer Formulareingaben in Cookies oder im lokalen Browserspeicher. Bei Bereitstellung über einen Webserver können durch dessen Betreiber technische Zugriffsdaten verarbeitet werden.</p><h3>Vor dem echten Betrieb zu ergänzen</h3><p>[Verantwortlicher und Kontakt], tatsächlicher Hostinganbieter, konkrete Zwecke und Rechtsgrundlagen, Empfänger und Versanddienst, Aufbewahrungsfristen sowie Betroffenenrechte und zuständige Aufsicht sind anhand des tatsächlichen Betriebs zu ergänzen.</p><p>Dieser Demo-Hinweis ist keine vollständige Datenschutzerklärung für einen echten Betrieb.</p>'}};
$$('[data-legal]').forEach(b=>b.addEventListener('click',()=>{const copy=legalCopy[b.dataset.legal];returnFocus=b;$('#legal-title').textContent=copy.title;$('#legal-content').innerHTML=copy.html;legal.setAttribute('aria-labelledby','legal-title');legal.showModal()}));$('#close-legal').addEventListener('click',()=>legal.close());legal.addEventListener('close',()=>returnFocus?.focus());legal.addEventListener('click',e=>{if(e.target===legal){const r=legal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)legal.close()}});
if(config.formEndpoint){$('.demo-warning').hidden=true;$('.privacy-note').textContent='Ihre Angaben werden zur Bearbeitung Ihrer Anfrage übermittelt. Bitte lesen Sie vor der Anfrage die Datenschutzerklärung.';$('.form-top .demo').hidden=true;}
const businessTitle=config.businessName+' – Hausmeisterservice';document.title=businessTitle+' in '+config.region+' | '+(config.formEndpoint?'Anfrage':'Demo');
if(config.phone){const b=$$('.contact-details b')[0],a=document.createElement('a');a.href='tel:'+config.phone.replace(/[^+\d]/g,'');a.textContent=config.phone;b.replaceChildren(a)}if(config.email){const b=$$('.contact-details b')[1],a=document.createElement('a');a.href='mailto:'+config.email;a.textContent=config.email;b.replaceChildren(a)}
$$('.brand').forEach(el=>{const label=el.querySelector(':scope > span:last-child'); if(label && !label.classList.contains('mark')) {const sub=label.querySelector('small');label.replaceChildren(document.createTextNode(config.businessName));if(sub)label.append(sub)}else if(!el.querySelector('.mark'))el.textContent=config.businessName});
$('.hero-image img').src=config.images.hero;$$('.example-grid img')[0].src=config.images.garden;$$('.example-grid img')[1].src=config.images.stairs;
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_service_inquiry',description:'Öffnet die lokale Anfrage und wählt eine Leistung vor. Übermittelt keine Daten.',inputSchema:{type:'object',properties:{service:{type:'string',enum:serviceNames}},required:['service'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='service'))throw new Error('Ungültige Eingabe');return startService(input.service)}})).catch(()=>{})}catch{}}
window.addEventListener('pagehide',()=>photos.forEach(p=>URL.revokeObjectURL(p.url)));
